questions = []
for p in passages:
    title = p["title"]
    text = p["text"].strip()
    for q in p["questions"]:
        question_text = f"阅读下面的文字，完成后面的问题。\n\n【{title}】\n{text}\n\n{q['q']}"
        questions.append({
            "id": q["id"],
            "type": "single_choice",
            "question": question_text,
            "options": q["opts"],
            "answer": q["ans"],
            "analysis": q["analysis"],
            "knowledge_tag": "现代文阅读",
            "ability_tag": q["ability"],
            "difficulty": q["d"],
        })

print(f"生成 {len(questions)} 题")
with open('src/data/questions_junior_chinese_reading.json', 'w') as f:
    json.dump(questions, f, ensure_ascii=False, indent=2)

data = json.load(open('src/data/questions_junior_chinese_reading.json'))
print(f"验证: {len(data)} 题, 类型: {set(q['type'] for q in data)}")
print(f"能力: {set(q['ability_tag'] for q in data)}")
print(f"难度: {set(q['difficulty'] for q in data)}")
